        if(RegionalDomains.Enabled(Snapshot()))box.AddChild(new Label{Text="この委任は家の資金による現地調達も月200文まで含みます。家全体の予算残額も上限。予算変更・私財拠出は当主のみ。",AutowrapMode=TextServer.AutowrapMode.WordSmart});
