        foreach(var p in v.Reports.Reverse().Take(4)){var o=p.Observation!;box.AddChild(new Label{Text=DateOnly.Parse(Snapshot().EpochDate).AddDays((int)(o.ObservedAt/86400)).ToString("yyyy-MM-dd")+"観測 / "+NewGameWorld.SiteName(o.Site.Value)+$"\n報告時：家の米 {o.Accounts.HouseRice}kg・村の不足 {o.Accounts.Hunger}kg\n現在の値を示すものではありません。",AutowrapMode=TextServer.AutowrapMode.WordSmart});if(o.Regional is {} regional)box.AddChild(new Label{Text=$"同じ観測時点：家の資金 {regional.HouseCash}文 / 月予算 {regional.MonthlyBudget}文 / 残枠 {regional.BudgetRemaining}文\n木材 {regional.Materials.Wood}kg・武具 {regional.Materials.Weapons}組",AutowrapMode=TextServer.AutowrapMode.WordSmart});if(p.Sender==Session.PlayerControl)Button("この観測原本を再送する",()=>Run(Input(StewardAction.ResendReport,o.Site,p.Grant) with{Report=p.Id}));}
        foreach(var mail in Branch(Session.PlayerControl).Knowledge.Messages.Where(m=>m.KnownBody==null&&Snapshot().Messaging.Messages.Any(p=>p.Id==m.Id.Value&&p.Kind is CommunityStewardship.ReportKind or CommunityStewardship.AckKind or CommunityStewardship.RevokeKind)).ToArray()){var paper=mail;Button("届いた書状を開く："+PersonName(new(paper.Sender)),()=>{var result=Session.Open(Session.PlayerControl,paper.Id,shown);if(result.Code is not(ResultCode.Accepted or ResultCode.AlreadyAccepted)){feedback.Text=result.VisibleReason;return;}popup.Hide();Refresh();ShowStewardship();});}Button("読み直す",()=>{popup.Hide();ShowStewardship();});Button("地図へ戻る",()=>popup.Hide());popup.PopupHide+=()=>popup.QueueFree();popup.PopupCentered(new Vector2I(570,520));
    }
